    @Test public void datesRespectZonesLabelsAndUnknownValues(){assertEquals("2026/10/15 00:15 投稿",VideoRows191.date("2026-10-14T15:15:00Z","投稿"));for(String source:new String[]{"2026-10-15T00:15:00+0900","2026-10-15T00:15:00.000+09:00","2026年10月15日 00時15分 投稿","2026/10/15 00:15 登録","2026年10月15日 00:15"})assertEquals(source,"2026/10/15 00:15 投稿",VideoRows191.date(source,"投稿"));for(String source:new String[]{"","unknown","0","2026-02-30 00:15"})assertEquals("",VideoRows191.date(source,"投稿"));}
    @Test public void rankingAndSearchRetainTitleAndRankAndShareStylesInBothThemes(){for(String theme:new String[]{"dark","light"}){PreferenceManager.getDefaultSharedPreferences(a).edit().putString("app_theme",theme).commit();LinearLayout root=root();Row row=row("2026-10-15 00:15:00");bind(root,new Adapter(6,row),row);assertEquals("2026/10/15 00:15 投稿",value(root,0x7f08015e));assertEquals("Uploader",value(root,0x7f0801e2));assertEquals(row.a("title"),value(root,0x7f0801b4));assertEquals("999",value(root,0x7f080165));TextView title=(TextView)root.findViewById(0x7f0801b4);assertEquals(15,title.getTextSize()/a.getResources().getDisplayMetrics().scaledDensity,.01);assertEquals(theme.equals("dark")?0xffeeeeee:0xff202124,title.getCurrentTextColor());LinearLayout column=(LinearLayout)root.findViewById(0x7f0800e3);assertEquals(2,column.indexOfChild(root.findViewById(0x7f0801e2)));assertEquals(3,column.indexOfChild(root.findViewById(0x7f0801d3)));assertEquals("Views 1,234, Comments 55, Likes 6, Mylists 7",root.findViewById(0x7f0801d3).getContentDescription().toString());for(int width:new int[]{320,600}){root.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));root.layout(0,0,width,root.getMeasuredHeight());assertEquals(PanelUi.dp(a,4),((RelativeLayout.LayoutParams)column.getLayoutParams()).rightMargin);assertEquals(((View)column.getParent()).getWidth()-PanelUi.dp(a,4),column.getRight());TextView rank=(TextView)root.findViewById(0x7f080165);assertEquals(60,rank.getTextSize()/a.getResources().getDisplayMetrics().scaledDensity,.01);assertEquals(0xff5f7593,rank.getCurrentTextColor());assertEquals(-2,root.findViewById(0x7f080167).getLayoutParams().width);assertEquals(9f/16,root.findViewById(0x7f0800cd).getHeight()/(float)root.findViewById(0x7f0800cd).getWidth(),.01);assertTrue(title.getLineCount()>1);}}}
    @Test public void mylistUsesAddedAndPostedIndependentlyWithApiCounts()throws Exception{LinearLayout root=root();Row row=row("2019年01月17日 00時17分 登録");HistorySupport.capture(row,new JSONObject().put("registeredAt","2018-12-31T12:34:00+09:00").put("owner",new JSONObject().put("name","Channel")).put("count",new JSONObject().put("view",12).put("like",4)));bind(root,new Adapter(5,row),row);assertEquals("2019/01/17 00:17 登録",value(root,0x7f08015e));TextView posted=(TextView)root.findViewWithTag(VideoRows191.POSTED);assertEquals("2018/12/31 12:34 投稿",posted.getText().toString());assertEquals("Channel",value(root,0x7f0801e2));assertEquals("Views 12, Likes 4",root.findViewById(0x7f0801d3).getContentDescription().toString());LinearLayout parent=(LinearLayout)posted.getParent();assertTrue(parent.indexOfChild(posted)>parent.indexOfChild(root.findViewById(0x7f0801d3)));}
