    @Test public void recycledRowsClearCacheStatusAndUnknownMetadataWithoutDroppingClickTargets()throws Exception{LinearLayout root=root();Row cache=row("");CacheListing.INFO.put(cache,CacheRowInfo.from(new JSONObject().put("postedAt","2026-10-04T15:20:00+09:00").put("ownerName","Cache owner").put("viewCount",117192),66600000,false));bind(root,new Adapter(0,cache),cache);assertEquals("Cache owner",value(root,0x7f0801e2));assertEquals("2026/10/04 15:20 投稿",value(root,0x7f08015e));assertTrue(VideoRows191.transfer(root).getText().toString().contains("未完了"));assertEquals("Views 117,192",root.findViewById(0x7f0801d3).getContentDescription().toString());final int[] called={0};root.setOnClickListener(v->called[0]++);root.setOnLongClickListener(v->{called[0]+=10;return true;});Row next=row("");next.y="";next.a("videoinfo","");bind(root,new Adapter(5,next),next);assertEquals(View.GONE,root.findViewById(0x7f08015e).getVisibility());assertEquals(View.GONE,root.findViewById(0x7f0801e2).getVisibility());assertEquals(View.GONE,root.findViewById(0x7f0801d3).getVisibility());assertEquals(View.GONE,root.findViewWithTag(VideoRows191.POSTED).getVisibility());assertEquals(View.GONE,VideoRows191.transfer(root).getVisibility());root.performClick();root.performLongClick();assertEquals(11,called[0]);assertEquals("23:20",value(root,0x7f0800df));}
